  "explanation": "Diabetul zaharat, prin el însuși, nu este considerat un factor de risc — Corect: Textul precizează explicit că diabetul în sine nu este un factor de risc.\n\nMetforminul poate precipita acidoza lactică și ar trebui oprit dacă creatinina depășește 130 µmol/L — Corect: Textul indică oprirea metforminului dacă creatinina depășește 130 µmol/L, cu reluare doar când funcția renală revine la nivelul de bază.\n\nDopamina, teofilina și dializa profilactică s-au dovedit benefice în prevenție — Incorect: Textul afirmă că dopamina, teofilina și dializa profilactică nu sunt benefice.\n\nN-acetilcisteina administrată 48 de ore înainte oferă un beneficiu major, demonstrat consistent — Incorect: N-acetilcisteina poate oferi cel mult un beneficiu marginal, nu unul major.\n\nHidratarea peri-procedurală trebuie evitată, pentru a nu precipita supraîncărcarea volemică — Incorect: Prevenția include hidratarea cu 1 L ser fiziologic 0,9% sau bicarbonat 1,4%, cu evitarea supraîncărcării doar la pacienții la risc, nu omiterea hidratării.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 36, p. 1392, Boala cronică de rinichi — Nefropatia de contrast: prevenție (context de injurie renală acută) (pagini PDF: 352).",
