  "explanation": "Ciclosporina sau tacrolimusul pot fi eficiente, dar trebuie continuate pe termen lung pentru a preveni recidiva la întrerupere — Corect: Textul precizează eficiența ciclosporinei sau tacrolimusului și necesitatea continuării pe termen lung ca să prevină recidiva.\n\nCiclofosfamida 1,5–2,0 mg/kg pe zi timp de 8–12 săptămâni, cu prednisolon 7,5–15 mg/zi, crește probabilitatea remisiunii pe termen lung — Corect: Dozele și durata de 8-12 săptămâni de ciclofosfamidă, cu prednisolon 7,5-15 mg/zi, cresc șansa remisiunii de lungă durată.\n\nLa copii nu trebuie prescrise mai mult de două cure de ciclofosfamidă, din cauza riscului de infertilitate — Corect: La copii, limita de două cure este justificată de infertilitate (azoospermie și insuficiență ovariană).\n\nLevamisolul 2,5 mg/kg (maximum 150 mg) în zile alternative poate menține remisiunea la copiii dependenți de corticoizi — Corect: Levamisolul 2,5 mg/kg până la 150 mg în zile alternative este util la copiii corticodependenți.\n\nRituximabul, anticorp anti-CD20, este inactiv în această indicație, ținând cont că NLM ar fi o boală doar podocitară, fără rol al liniei B — Incorect: Rituximabul, anticorp monoclonal anti-CD20, este menționat ca opțiune; NLM nu este prezentată ca fiind incompatibilă cu terapia B.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 36, p. 1355, 1354, Glomerulul și afectarea glomerulară — Nefropatia cu leziuni minime: agenți de linia a doua (pagini PDF: 335, 334).",
