  "explanation": "Este explicată integral prin faptul că ficatul nu poate sintetiza albumină — Incorect: Ficatul sănătos sintetizează 10-12 g albumină pe zi; nu este incapabil.\n\nRezultă doar din scăderea PCSK9, fără catabolism tubular — Incorect: PCSK9 este invocată la hiperlipidemie (internalizarea receptorilor LDL), nu ca mecanism unic al hipoalbuminemiei.\n\nO explicație parțială este creșterea catabolismului proteinelor reabsorbite, în mare parte albumină, în tubii proximali — Corect: Textul oferă exact această explicație parțială: catabolismul proteinelor reabsorbite în tubii proximali.\n\nApare numai când proteinuria depășește 70 g/zi, egalând aportul dietetic britanic — Incorect: Pragul citat pentru sindrom este 3,5 g/zi, nu 70 g.\n\nHDL crește constant, raportul LDL:HDL scăzând — Incorect: HDL este neschimbat sau scăzut, iar raportul LDL:HDL crește.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 36, p. 1353, Glomerulul și afectarea glomerulară — Hipoalbuminemia: catabolism tubular (pagini PDF: 333).",
