  "explanation": "Degenerarea chistică apare de regulă în rinichii nefuncționali tratați prin dializă sau transplant — Corect: Apariția pe rinichi nefuncționali dializați/transplantați este din text.\n\nAceste chisturi dobândite au potențial de malignizare — Corect: Potențialul de malignizare este explicit.\n\nOcazional, chisturile simple mari produc durere și/sau hematurie prin sângerare intrachistică — Corect: Durerea/hematuria prin sângerare intrachistică sunt menționate la chisturile simple mari.\n\nSunt identice BPRAD genetică și impun screeningul anevrismelor la toți dializații peste 30 de ani — Incorect: Nu echivalează BPRAD și nu impun screening de anevrism „la toți dializații”.\n\nNu au potențial malign, spre deosebire de chisturile simple ale vârstnicului — Incorect: Relația de malignitate este inversă: dobânditele au potențial, simplele vârstnicului de obicei nu.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 36, p. 1405, Bolile renale chistice — Boala chistică dobândită și malignizare (pagini PDF: 365).",
