  "explanation": "GSFS primară reapare frecvent și duce la pierderea precoce a grefei; reapar și GNMC, nefropatia diabetică și nefropatia cu IgA — Corect: Lista de recurențe, cu GSFS ca pierdere precoce, este din text.\n\nFibroza interstițială cu atrofie tubulară, numită anterior nefropatie cronică de allogrefă, este un aspect histologic frecvent — Corect: IFTA ca termen actual pentru fosta nefropatie cronică de allogrefă este explicită.\n\nDeclinul progresiv se asociază cu proteinurie ușoară-moderată (<3 g/zi); intervențiile nu s-au dovedit încă benefice — Corect: Proteinuria <3 g/zi și absența unei intervenții dovedite sunt citate.\n\nImunosupresia crește riscul tumorilor cutanate, inclusiv carcinoame bazocelulare și spinocelulare — Corect: BCC și SCC sunt menționate.\n\nGSFS nu recidivează pe grefă, proteinuria >10 g/zi fiind necesară diagnosticului de IFTA — Incorect: GSFS recidivează; pragul de proteinurie al declinului este <3 g/zi, nu >10.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 36, p. 1404, Boala cronică de rinichi — Recurențe pe grefă și IFTA (pagini PDF: 364).",
